<?php
/** Offline manager operations test. Run with wp eval-file scripts/test-offline-operations.php. */
if(!defined('ABSPATH')){exit(1);}global $wpdb;$p=$wpdb->prefix.'ps_';$ids=array();$pass=0;$fail=0;$assert=static function($ok,$msg)use(&$pass,&$fail){echo($ok?'PASS: ':'FAIL: ').$msg."\n";$ok?++$pass:++$fail;};try{$token='ops-'.wp_generate_uuid4();$wpdb->insert($p.'tenants',array('name'=>'Offline Operations Test','slug'=>$token,'primary_contact_email'=>"$token@example.test",'status'=>'active'));$ids['tenant']=(int)$wpdb->insert_id;$wpdb->insert($p.'tenants',array('name'=>'Other Tenant','slug'=>$token.'-other','primary_contact_email'=>"other-$token@example.test",'status'=>'active'));$ids['other']=(int)$wpdb->insert_id;$wpdb->insert($p.'branches',array('tenant_id'=>$ids['tenant'],'name'=>'Main','code'=>'MAIN','is_active'=>1));$ids['branch']=(int)$wpdb->insert_id;$wpdb->insert($p.'offline_devices',array('tenant_id'=>$ids['tenant'],'branch_id'=>$ids['branch'],'user_id'=>1,'client_id'=>'test_'.$token,'device_name'=>'Manager Test Device','encrypted_secret'=>'never-return-this','secret_fingerprint'=>'1234567890abcdef','status'=>'active','expires_at'=>gmdate('Y-m-d H:i:s',time()+DAY_IN_SECONDS),'created_at'=>current_time('mysql',true)));$ids['device']=(int)$wpdb->insert_id;$insert_mutation=static function($status,$client,$base='old')use($wpdb,$p,&$ids){$payload=wp_json_encode(array('supplier_id'=>999,'items'=>array()));$wpdb->insert($p.'offline_mutations',array('tenant_id'=>$ids['tenant'],'branch_id'=>$ids['branch'],'device_id'=>$ids['device'],'user_id'=>1,'client_mutation_id'=>$client,'mutation_type'=>'stock.receive','base_version'=>$base,'payload'=>$payload,'payload_hash'=>hash('sha256',$payload),'status'=>$status,'attempt_count'=>0,'received_at'=>current_time('mysql',true)));return(int)$wpdb->insert_id;};$conflict=$insert_mutation('conflict','conflict-1');$queued=$insert_mutation('requires_online_replay','queued-1');$applied=$insert_mutation('applied','applied-1');$service=new \PharmaSure\Offline\Services\OperationsService();$devices=$service->devices($ids['tenant']);$assert(1===count($devices),'tenant device inventory is returned');$assert(!array_key_exists('encrypted_secret',$devices[0]),'device secrets are excluded from administration results');$detail=$service->mutation($ids['tenant'],$conflict);$assert(is_array($detail)&&is_array($detail['payload']),'mutation detail decodes the stored payload');$assert(is_wp_error($service->mutation($ids['other'],$conflict)),'mutation detail is tenant isolated');$assert(is_wp_error($service->discard($ids['tenant'],$queued,1,'')),'discard requires a manager reason');$assert(is_wp_error($service->discard($ids['tenant'],$applied,1,'duplicate')),'applied mutations cannot be discarded');$discard=$service->discard($ids['tenant'],$queued,1,'Duplicate entry confirmed');$assert('discarded'===($discard['status']??''),'queued mutation can be safely discarded');$rebase=$service->rebase($ids['tenant'],$conflict,1,'Stock state reviewed');$assert('requires_online_replay'===($rebase['status']??'')&&!empty($rebase['base_version']),'conflict rebase captures a fresh authoritative version');$monitor=$service->monitor($ids['tenant']);$assert(isset($monitor['counts']['discarded'])&&isset($monitor['security_alerts']),'monitor reports replay state and security alerts');$alerts=new \PharmaSure\Offline\Services\SecurityAlertService();for($i=0;$i<5;$i++){$alert=$alerts->record($ids['tenant'],1,'offline_signature_failure','Rejected offline device signature.');}$assert('critical'===$alert['severity'],'repeated signature failures escalate to critical');$description=$wpdb->get_var($wpdb->prepare("SELECT description FROM {$p}security_events WHERE tenant_id=%d AND event_type='offline_signature_failure' ORDER BY id DESC LIMIT 1",$ids['tenant']));$assert(!str_contains($description,'never-return-this')&&!str_contains($description,'signature='),'security alerts contain no credentials or signature material');}catch(Throwable $e){++$fail;echo'FAIL: unexpected exception: '.$e->getMessage()."\n";}finally{if(!empty($ids['tenant'])){foreach(array('audit_events','security_events','offline_mutations','offline_devices','branches')as$t){$wpdb->delete($p.$t,array('tenant_id'=>$ids['tenant']));}$wpdb->delete($p.'tenants',array('id'=>$ids['tenant']));}if(!empty($ids['other'])){$wpdb->delete($p.'tenants',array('id'=>$ids['other']));}}echo"Offline operations tests: $pass passed, $fail failed.\n";if($fail){throw new RuntimeException('Offline operations tests failed.');}
